(function () {const config =Object.assign({enabled:false,consentGranted:false,provider:'',measurementId:'',searchConsoleVerificationToken:''},window.DARCY_ANALYTICS_CONFIG ||{});const events =[];const caseStudyRoutes =new Set(['case-study','pauncefoot-house','canada-common','farleigh-school']);function track(name,parameters ={}) {if (!config.enabled ||!config.consentGranted ||!config.measurementId) return;const event ={name,parameters,timestamp:new Date().toISOString() };events.push(event);if (Array.isArray(window.dataLayer)) window.dataLayer.push({event:name,...parameters });if (typeof window.gtag ==='function') window.gtag('event',name,parameters);} function trackRoute() {const route =window.location.hash.slice(1) ||'home';if (caseStudyRoutes.has(route)) track('case_study_view',{route });if (route ==='insights') track('insight_view',{route });} document.addEventListener('click',(event) =>{const link =event.target.closest &&event.target.closest('a[href]');if (!link) return;const href =link.getAttribute('href') ||'';if (href ==='#contact') track('start_conversation_click',{location:link.className ||'link'});if (href.startsWith('tel:')) track('phone_click',{destination:href.slice(4) });if (href.startsWith('mailto:')) track('email_click',{destination:href.slice(7) });});document.addEventListener('submit',(event) =>{if (event.target &&event.target.tagName ==='FORM') track('contact_form_submit');});window.addEventListener('hashchange',trackRoute);window.DarcyAnalytics =Object.freeze({configure(next ={}) {Object.assign(config,next);},grantConsent() {config.consentGranted =true;},revokeConsent() {config.consentGranted =false;},track,events });if (config.searchConsoleVerificationToken) {const meta =document.createElement('meta');meta.name ='google-site-verification';meta.content =config.searchConsoleVerificationToken;document.head.appendChild(meta);} trackRoute();})();